static const size_t k_entity_table_len = 2125;

bool mdit_entity_lookup(const char *name, size_t len,
                        const char **out, size_t *out_len)
{
    if (name == NULL || len == 0) {
        if (out)     *out = NULL;
        if (out_len) *out_len = 0;
        return false;
    }
    /* Binary search on the sorted name table. */
    size_t lo = 0, hi = k_entity_table_len;
    while (lo < hi) {
        size_t mid = lo + (hi - lo) / 2;
        const mdit_entity_record *r = &k_entity_table[mid];
        size_t n = len < r->name_len ? len : r->name_len;
        int c = memcmp(name, (const char *)k_entity_pool + r->name_off, n);
        if (c == 0) {
            if (len == r->name_len) {
                if (out)     *out = (const char *)k_entity_pool + r->value_off;
                if (out_len) *out_len = r->value_len;
                return true;
            }
            if (len < r->name_len) c = -1; else c = 1;
        }
        if (c < 0) hi = mid; else lo = mid + 1;
    }
    if (out)     *out = NULL;
    if (out_len) *out_len = 0;
    return false;
}

size_t mdit_entity_count(void)
{
    return k_entity_table_len;
}
